CREATE TABLE IF NOT EXISTS editions (edition_date DATE PRIMARY KEY, collected_at VARCHAR(35) NOT NULL, bundle LONGTEXT NOT NULL, bundle_hash CHAR(64) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS entries (id CHAR(24) PRIMARY KEY, kind VARCHAR(8) NOT NULL, edition_date DATE NOT NULL, url_hash CHAR(64) NOT NULL, category VARCHAR(40) NOT NULL, region VARCHAR(12) NOT NULL, title VARCHAR(300) NOT NULL, score INT NOT NULL, body LONGTEXT NOT NULL, UNIQUE KEY daily_entry(kind,edition_date,url_hash), KEY edition_kind(edition_date,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS collection_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, edition_date DATE NOT NULL, status VARCHAR(16) NOT NULL, detail TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
